"""Write and read Markdown (GitHub-flavored) pipe tables.

``format_table`` writes a header line, a delimiter line, and one line per
row, separated by ``\\n`` with no trailing newline. Every line is ``| ``,
then the column cells joined by `` | ``, then `` |``.

Cell text is ``str(value)``, or empty for ``None``, with each ``|``
escaped as ``\\|``. A row shorter than the header is padded with empty
cells; a longer one raises ``ValueError``. Each column is as wide as its
longest cell text (after escaping, and including the header), and at
least 3.

Cells are padded with spaces to the column width according to the
column's alignment: ``"left"`` or ``None`` pads on the right, ``"right"``
pads on the left, and ``"center"`` pads both sides equally, with any odd
space on the right. ``align`` gives one alignment per column (default all
``None``); any other value, or a list of the wrong length, raises
``ValueError``.

Delimiter cells are dashes filling the column width, with a colon replacing
the first dash for ``"left"``, the last for ``"right"``, and both for
``"center"`` (``:--``, ``--:``, ``:-:`` at width 3).

``parse_table`` reads such a table back, tolerating any padding and missing
leading or trailing pipes: it returns the header and the rows as lists of
stripped strings with ``\\|`` unescaped, and the alignment of each column
from the delimiter line (``None`` for plain dashes). Each delimiter cell
must be one or more dashes with an optional colon at either end. Text that
isn't a table (fewer than two lines, a bad delimiter line, or a delimiter
line or row with a different number of cells than the header) raises
``ValueError``.
"""

from __future__ import annotations

import re

_ALIGNMENTS = ("left", "right", "center", None)
_DELIMITER = re.compile(r"(:?)-+(:?)")


def _cell_text(value: object) -> str:
    text = "" if value is None else str(value)
    return text.replace("|", "\\|")


def _pad(text: str, width: int, alignment: str | None) -> str:
    space = width - len(text)
    if alignment == "right":
        return " " * space + text
    if alignment == "center":
        left = space // 2
        return " " * left + text + " " * (space - left)
    return text + " " * space


def _delimiter(width: int, alignment: str | None) -> str:
    cell = ["-"] * width
    if alignment in ("left", "center"):
        cell[0] = ":"
    if alignment in ("right", "center"):
        cell[-1] = ":"
    return "".join(cell)


def _line(cells: list[str]) -> str:
    return "| " + " | ".join(cells) + " |"


def format_table(
    header: list, rows: list[list], align: list[str | None] | None = None
) -> str:
    """Write a Markdown table."""
    columns = len(header)
    if align is None:
        align = [None] * columns
    if len(align) != columns:
        raise ValueError(f"align has {len(align)} entries for {columns} columns")
    for alignment in align:
        if alignment not in _ALIGNMENTS:
            raise ValueError(f"invalid alignment: {alignment!r}")

    head = [_cell_text(value) for value in header]
    body = []
    for row in rows:
        if len(row) > columns:
            raise ValueError(f"row has {len(row)} cells for {columns} columns")
        cells = [_cell_text(value) for value in row]
        body.append(cells + [""] * (columns - len(cells)))

    widths = [
        max([3, len(head[i])] + [len(cells[i]) for cells in body])
        for i in range(columns)
    ]

    def render(cells: list[str]) -> str:
        return _line([_pad(c, w, a) for c, w, a in zip(cells, widths, align)])

    lines = [render(head), _line([_delimiter(w, a) for w, a in zip(widths, align)])]
    lines.extend(render(cells) for cells in body)
    return "\n".join(lines)


def _split_row(line: str) -> list[str]:
    """Split a table line at unescaped pipes into stripped, unescaped cells."""
    line = line.strip()
    pieces = []
    current = []
    i = 0
    while i < len(line):
        if line.startswith("\\|", i):
            current.append("|")
            i += 2
            continue
        if line[i] == "|":
            pieces.append("".join(current))
            current = []
        else:
            current.append(line[i])
        i += 1
    pieces.append("".join(current))
    # The line is stripped, so a leading pipe leaves an empty first piece
    # and an unescaped trailing pipe an empty last one.
    trailing = len(pieces) > 1 and line.endswith("|") and pieces[-1] == ""
    if line.startswith("|"):
        pieces.pop(0)
    if trailing and len(pieces) > 1:
        pieces.pop()
    return [piece.strip() for piece in pieces]


def parse_table(
    text: str,
) -> tuple[list[str], list[list[str]], list[str | None]]:
    """Read a Markdown table into its header, rows, and alignments."""
    lines = text.splitlines()
    while lines and not lines[0].strip():
        lines.pop(0)
    while lines and not lines[-1].strip():
        lines.pop()
    if len(lines) < 2:
        raise ValueError("a table needs a header line and a delimiter line")

    header = _split_row(lines[0])
    delimiters = _split_row(lines[1])
    if len(delimiters) != len(header):
        raise ValueError(
            f"delimiter line has {len(delimiters)} cells"
            f" for {len(header)} columns"
        )
    align: list[str | None] = []
    for cell in delimiters:
        match = _DELIMITER.fullmatch(cell)
        if match is None:
            raise ValueError(f"invalid delimiter cell: {cell!r}")
        left, right = bool(match.group(1)), bool(match.group(2))
        if left and right:
            align.append("center")
        elif left:
            align.append("left")
        elif right:
            align.append("right")
        else:
            align.append(None)

    rows = []
    for lineno, line in enumerate(lines[2:], start=3):
        cells = _split_row(line)
        if len(cells) != len(header):
            raise ValueError(
                f"line {lineno}: row has {len(cells)} cells"
                f" for {len(header)} columns"
            )
